data.definition:
flowchart LR
  A["Simple Reflex Agent
Condition-action rules
(e.g., thermostat)"] --> B
  B["Model-Based Reflex Agent
Internal state + condition-action
(e.g., self-driving car avoiding obstacles)"] --> C
  C["Goal-Based Agent
Goals + search/planning
(e.g., route-finding GPS)"] --> D
  D["Utility-Based Agent
Utility function + decision theory
(e.g., recommendation system)"] --> E
  E["Learning Agent
Performance element + critic + problem generator
(e.g., AlphaGo, personal assistant)"]

  classDef reflex fill:#fff8c5,stroke:#9a6700;
  classDef model fill:#d1f3d8,stroke:#1a7f37;
  classDef goal fill:#eddff8,stroke:#8250df;
  classDef utility fill:#ddf4ff,stroke:#0969da;
  classDef learning fill:#fceae8,stroke:#af291e;
  class A reflex;
  class B model;
  class C goal;
  class D utility;
  class E learning;
